   import analyzeSentiment from '../lib/analyzeSentiment';

   function TweetAnalysis({ tweet }) {
     const sentimentScore = analyzeSentiment(tweet.text);

     if (sentimentScore > 0) {
       return <p>Este tweet es positivo</p>;
     } else if (sentimentScore === 0) {
       return <p>Este tweet es neutro</p>;
     } else {
       return <p>Este tweet es negativo</p>;
     }
   }
   ```

