Aquí te presento un ejemplo de cómo leer un archivo línea por línea en C++ y contar el número de apariciones de una palabra específica:

```c++
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string wordToCount; // palabra a contar
    int count = 0; // contador de apariciones

    // leer palabra a contar desde el usuario
    cout << "Ingrese la palabra a contar: ";
    cin >> wordToCount;

    // abrir el archivo para leer
    ifstream file("archivo.txt");

    // chequear si el archivo se abrió correctamente
    if (!file.is_open()) {
        cerr << "Error al abrir el archivo." << endl;
        return 1; // indicar error
    }

    string line; // variable para almacenar cada línea del archivo

    // leer línea por línea y contar apariciones
    while (getline(file, line)) {
        size_t pos = line.find(wordToCount); // buscar posición de la palabra en la línea
        while (pos != string::npos) { // mientras haya más apariciones en la línea
            count++; // aumentar contador
            pos = line.find(wordToCount, pos + 1); // buscar siguiente aparición a partir de la última encontrada
        }
    }

    // cerrar el archivo
    file.close();

    // mostrar resultado
    cout << "La palabra '" << wordToCount << "' aparece " << count << " veces en el archivo." << endl;

    return 0;
}
```

En este ejemplo, se solicita al usuario la palabra a contar y luego se abre el archivo de texto especificado (`archivo.txt`) para leer línea por línea. En cada línea, se busca la posición de la palabra específica utilizando la función `find()` de la clase `string`. Si se encuentra una aparición, se aumenta el contador y se busca la siguiente aparición a partir de la última encontrada.

Una vez terminado el proceso de lectura, se cierra el archivo y se muestra el resultado al usuario. 

Recuerda que debes tener el archivo de texto en el mismo directorio que el programa para que este pueda abrirlo correctamente.

Aquí te presentamos un programa en C++ que encuentra los elementos comunes en dos matrices sin utilizar ninguna estructura de datos adicional:

```cpp
#include <iostream>
#include <algorithm>

using namespace std;

int main() {
    int m1_rows, m1_cols, m2_rows, m2_cols;

    cout << "Enter the dimensions of the first matrix (rows cols): ";
    cin >> m1_rows >> m1_cols;

    int matrix1[m1_rows][m1_cols];

    cout << "Enter the elements of the first matrix:" << endl;
    for (int I = 0; I < m1_rows; i++) {
        for (int j = 0; j < m1_cols; j++) {
            cin >> matrix1[i][j];
        }
    }

    cout << "Enter the dimensions of the second matrix (rows cols): ";
    cin >> m2_rows >> m2_cols;

    int matrix2[m2_rows][m2_cols];

    cout << "Enter the elements of the second matrix:" << endl;
    for (int I = 0; I < m2_rows; i++) {
        for (int j = 0; j < m2_cols; j++) {
            cin >> matrix2[i][j];
        }
    }

    // Find the minimum number of rows and columns between the two matrices
    int min_rows = min(m1_rows, m2_rows);
    int min_cols = min(m1_cols, m2_cols);

    // Initialize the result matrix with all elements set to -1
    int result_matrix[min_rows][min_cols];
    for (int I = 0; I < min_rows; i++) {
        for (int j = 0; j < min_cols; j++) {
            result_matrix[i][j] = -1;
        }
    }

    // Traverse both matrices and find common elements
    int common_count = 0;
    for (int I = 0; I < min_rows; i++) {
        for (int j = 0; j < min_cols; j++) {
            if (matrix1[i][j] == matrix2[i][j] && matrix1[i][j] != -1) {
                result_matrix[common_count][0] = matrix1[i][j];
                result_matrix[common_count][1] = i;
                result_matrix[common_count][2] = j;
                common_count++;
            }
        }
    }

    // Print the result matrix
    cout << "Common elements:" << endl;
    if (common_count == 0) {
        cout << "No common elements found." << endl;
    } else {
        for (int I = 0; I < common_count; i++) {
            cout << result_matrix[i][0] << " ";
        }
        cout << endl;

